  if(active?.length){onNotice("Membrul are deja un pontaj activ. ĂŽnchide tura existentÄ Ă®nainte de a Ă®ncepe alta.");return;}
  const {error}=await supabase.from("attendance").insert({officer_id:target,shift_start:new Date().toISOString()});
